with valid as (select *, round(pressure, 1) as pressure_rounded, coalesce(pressure, 0) as pressure_filled from device_readings where reading_ts > date '2025-09-01'), prev_events as (select *, lag(reading_ts) over (partition by device_code order by reading_ts asc, id asc) as prev_reading_ts from valid), flagged as (select *, case when prev_reading_ts is null or reading_ts > prev_reading_ts + interval '20' minute then 1 else 0 end as new_group_flag from prev_events), sessions_device_readings as (select id, device_code, reading_ts, humidity, pressure, status_bits, pressure_rounded, pressure_filled, sum(new_group_flag) over (partition by device_code order by reading_ts asc, id asc rows between unbounded preceding and current row) as island_id from flagged) select island_id, sum(case when device_code = 'DV-02' then pressure else 0 end) as dv_02_pressure, count(distinct id) as distinct_ids, count(*) as cnt from sessions_device_readings group by 1 order by cnt desc
